create extension if not exists pgcrypto;
create table if not exists public.teachers (id uuid primary key default gen_random_uuid(), name text not null, email text not null unique, password_hash text, created_at timestamptz not null default now());
create table if not exists public.students (id uuid primary key default gen_random_uuid(), name text not null, register_no text not null unique, email text not null, password_hash text, created_at timestamptz not null default now());
create table if not exists public.questions (id bigint generated by default as identity primary key, teacher_id uuid references public.teachers(id) on delete set null, subject text not null, prompt text not null, options jsonb not null check (jsonb_array_length(options) = 4), correct_index integer not null check (correct_index between 0 and 3), created_at timestamptz not null default now());
create table if not exists public.attempts (id bigint generated by default as identity primary key, student_id uuid not null references public.students(id) on delete cascade, subject text not null, score integer not null check (score >= 0), total integer not null check (total > 0), correct integer not null check (correct >= 0), submitted_at timestamptz not null default now());
create index if not exists questions_subject_idx on public.questions(subject);
create index if not exists attempts_student_date_idx on public.attempts(student_id, submitted_at desc);
alter table public.teachers enable row level security;
alter table public.students enable row level security;
alter table public.questions enable row level security;
alter table public.attempts enable row level security;
